 function tabs(active){return '<div class="pc3-tabs-wrap"><div class="pc3-tabs">'+TABS.map(function(t){return '<button class="pc3-tab '+(t[0]===active?'active':'')+'" onclick="_rp2ProductsSetTab(\''+t[0]+'\')">'+t[2]+' '+t[1]+'</button>'}).join('')+'</div></div>'}
 function empty(title,copy){return '<div class="pc3-empty"><strong>'+esc(title)+'</strong><span>'+esc(copy)+'</span></div>'}
 function posture(g){if(!g.products.length)return{tone:'info',title:'The product workspace is ready for its first catalog item',copy:'Add or connect products, then build customer-specific recommendations.'};if(g.warnings.length)return{tone:'warn',title:'Recommendation verification work is active',copy:g.warnings.length+' recommendation or sample warning'+(g.warnings.length===1?' needs':'s need')+' review.'};if(g.recommendations.filter(function(r){return r.status==='Selected'&&!r.quoteId}).length)return{tone:'info',title:'Selected recommendations are ready for Deal Desk handoff',copy:'Create draft quotes after price, availability, and timing verification.'};return{tone:'good',title:'The visible recommendation book is controlled',copy:'No active recommendation currently triggers a modeled compatibility, verification, expiration, or sample warning.'}}
 function icon(p){if(/hat|headwear|cap/i.test(p.category+' '+p.name))return'🧢';if(/drink|tumbler|bottle/i.test(p.category+' '+p.name))return'🥤';if(/bag/i.test(p.category+' '+p.name))return'🎒';if(/jacket|vest/i.test(p.category+' '+p.name))return'🧥';return'👕'}
 function productCard(p,g){var fav=!!g.favorites[productKey(p)];return '<div class="pc3-product '+p.source+'" data-pc520="1" data-brand="'+esc(p.brand)+'" data-category="'+esc(p.category)+'" data-stock="'+esc(p.stockStatus)+'" data-source="'+esc(p.source)+'" data-search="'+esc((p.brand+' '+p.name+' '+p.sku+' '+p.category+' '+p.tags.join(' ')).toLowerCase())+'"><div class="pc3-product-img">'+(p.imageUrl?'<img src="'+esc(p.imageUrl)+'" alt="">':'<div class="pc3-product-placeholder">'+icon(p)+'</div>')+'</div><div class="pc3-product-body"><div class="pc3-product-brand">'+esc(p.brand+(p.sku?' · '+p.sku:''))+'</div><div class="pc3-product-name" onclick="_rp2ProductsOpen(\''+encodeURIComponent(p.key)+'\')">'+esc(p.name)+'</div><div class="pc3-product-meta">'+esc(p.category+' · '+p.stockStatus+' · Min '+p.minQty)+'</div><div class="pc3-product-price">'+(p.planningPrice?money(p.planningPrice):'Price TBD')+'</div><div class="pc3-product-copy">'+esc(p.priceNote||p.description||'Verify current pricing, inventory, and production timing.')+'</div><div class="pc3-tags"><span class="pc3-tag '+(/in stock|available/i.test(p.stockStatus)?'good':/limited/i.test(p.stockStatus)?'warn':'info')+'">'+esc(p.stockStatus)+'</span><span class="pc3-tag">'+esc(p.source==='local'?'Local Catalog':p.source==='purchase-history'?'Purchased History':'Connected Catalog')+'</span>'+(fav?'<span class="pc3-tag good">Favorite</span>':'')+'</div><div class="pc3-mini-actions"><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpen(\''+encodeURIComponent(p.key)+'\')">Open</button><button class="pc3-mini-btn good" onclick="_rp2ProductsRecommend(\''+encodeURIComponent(p.key)+'\')">Recommend</button><button class="pc3-mini-btn warn" onclick="_rp2ProductsFavorite(\''+encodeURIComponent(p.key)+'\')">'+(fav?'Unfavorite':'Favorite')+'</button>'+(p.editable?'<button class="pc3-mini-btn" onclick="_rp2ProductsEdit(\''+encodeURIComponent(p.key)+'\')">Edit</button>':'<button class="pc3-mini-btn" onclick="_rp2ProductsImport(\''+encodeURIComponent(p.key)+'\')">Import</button>')+'</div></div></div>'}
 function recCard(r){return '<div class="pc3-rec"><div class="pc3-rec-icon">'+icon(r.product)+'</div><div><div class="pc3-rec-title">'+esc(r.company+' · '+r.product.brand+' '+r.product.name)+'</div><div class="pc3-rec-meta">'+esc(r.tier+' · '+r.status+' · '+r.quantity+' units · '+r.decoration+' · '+(r.program||'No program'))+'</div><div class="pc3-rec-copy">'+esc(r.fitNotes||r.need||r.product.description||'Customer fit rationale not recorded.')+'</div><div class="pc3-tags"><span class="pc3-tag '+(r.score.score>=80?'good':r.score.score>=60?'info':'warn')+'">'+r.score.score+' fit score</span>'+(r.warnings.length?'<span class="pc3-tag risk">'+r.warnings.length+' warnings</span>':'<span class="pc3-tag good">Verified workflow</span>')+(r.quoteNumber?'<span class="pc3-tag info">'+esc(r.quoteNumber)+'</span>':'')+'</div></div><div class="pc3-rec-side">'+(r.planningUnitPrice?money(r.planningUnitPrice)+'/ea<br>'+money(r.planningTotal||r.planningUnitPrice*r.quantity):'Price TBD')+'<div class="pc3-mini-actions"><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpenRec(\''+encodeURIComponent(r.key)+'\')">Open</button>'+(r.editable?'<button class="pc3-mini-btn good" onclick="_rp2ProductsSample(\''+encodeURIComponent(r.key)+'\')">Sample</button><button class="pc3-mini-btn warn" onclick="_rp2ProductsQuote(\''+encodeURIComponent(r.key)+'\')">Quote</button>':'')+'</div></div></div>'}
 function warningRow(w){var title=w.type==='recommendation'?(w.item.company+' · '+w.item.product.name):w.item.company+' · '+w.item.productName;return '<div class="pc3-priority '+(w.level==='high'?'high':'medium')+'"><div class="pc3-priority-icon">'+(w.icon||'⚠')+'</div><div><div class="pc3-priority-title">'+esc(w.title+' · '+title)+'</div><div class="pc3-priority-copy">'+esc(w.copy)+'</div></div><div class="pc3-priority-side"><button class="pc3-mini-btn warn" onclick="'+(w.type==='recommendation'?'_rp2ProductsOpenRec(\''+encodeURIComponent(w.item.key)+'\')':'_rp2ProductsOpenSample(\''+encodeURIComponent(w.item.id)+'\')')+'">Review</button></div></div>'}

 function command(g){var p=posture(g),selected=g.recommendations.filter(function(r){return r.status==='Selected'&&!r.quoteId});return sectionHead('Product command center','Customer fit, verification, samples, assortment, and quote-readiness','Recommendations remain planning records until a verified quote is created.')+'<div class="pc3-summary"><div class="pc3-summary-label">Recommendation-book interpretation</div><div class="pc3-summary-title">'+esc(p.title)+'</div><div class="pc3-summary-copy">'+esc(p.copy)+'</div></div>'+sectionHead('Highest-priority product work','Compatibility, availability, timing, pricing, expiration, and sample exceptions','Every warning identifies the exact evidence that is missing or conflicting.')+(g.warnings.length?'<div class="pc3-priority-list">'+g.warnings.slice(0,10).map(warningRow).join('')+'</div>':empty('No active product warnings','No visible recommendation or sample currently triggers a modeled warning.'))+sectionHead('Selected options awaiting quote','Recommendations deliberately marked Selected without a Deal Desk quote','Verify price, inventory, decoration, and timing before handoff.')+(selected.length?'<div class="pc3-list">'+selected.map(recCard).join('')+'</div>':empty('No selected recommendation is waiting','Selected recommendations with quote handoff will leave this queue.'))+sectionHead('Catalog mix','Visible products by category','Connected and local product records are combined; local records take priority when SKU or name matches.')+'<div class="pc3-panel"><div class="pc3-chart"><canvas id="pc3-chart"></canvas></div></div>'}
 function filterBar(g){var brands={},cats={};g.products.forEach(function(p){brands[p.brand]=1;cats[p.category]=1});return '<div class="pc3-filterbar"><input id="pc3-search" placeholder="Search brand, style, SKU, category…" oninput="_rp2ProductsFilter()"><select id="pc3-brand" onchange="_rp2ProductsFilter()"><option value="">All brands</option>'+Object.keys(brands).sort().map(function(x){return'<option>'+esc(x)+'</option>'}).join('')+'</select><select id="pc3-category" onchange="_rp2ProductsFilter()"><option value="">All categories</option>'+Object.keys(cats).sort().map(function(x){return'<option>'+esc(x)+'</option>'}).join('')+'</select><select id="pc3-stock" onchange="_rp2ProductsFilter()"><option value="">Any availability</option><option>In Stock</option><option>Limited</option><option>Needs Verification</option><option>Unavailable</option></select><select id="pc3-source" onchange="_rp2ProductsFilter()"><option value="">Any source</option><option value="local">Local</option><option value="connected">Connected</option></select><div id="pc3-count" class="pc3-filtercount">'+g.products.length+' shown</div></div>'}
 function catalog(g){return sectionHead('Product catalog','Searchable product intelligence across connected and rep-created records','Catalog products and historical purchased SKUs are shown together. Purchased History proves prior buying behavior but does not represent current inventory, pricing, or lead time.')+'<div class="pc3-actions" style="margin-top:0"><button class="pc3-btn primary" onclick="_rp2ProductsNew()">＋ Add product</button></div>'+filterBar(g)+(g.products.length?'<div class="pc3-product-grid">'+g.products.map(function(p){return productCard(p,g)}).join('')+'</div>':empty('No products are visible','Add a local product or connect a product catalog.'))}
 function studioControls(g){var s=window._rp2ProductsStudio;return '<div class="pc3-filterbar" style="grid-template-columns:1fr 1fr 130px 180px auto"><select id="pc3-studio-company"><option value="">Choose company</option>'+g.companies.map(function(c){return'<option '+(c===s.company?'selected':'')+'>'+esc(c)+'</option>'}).join('')+'</select><input id="pc3-studio-program" value="'+esc(s.program)+'" placeholder="Program or use case"><input id="pc3-studio-qty" type="number" value="'+n(s.qty)+'"><select id="pc3-studio-decoration">'+METHODS.map(function(m){return'<option '+(m===s.decoration?'selected':'')+'>'+m+'</option>'}).join('')+'</select><button class="pc3-btn primary" onclick="_rp2ProductsApplyStudio()">Score products</button></div>'}
 function studio(g){var s=window._rp2ProductsStudio,rows=g.products.map(function(p){return{product:p,fit:fitScore(p,s.company,s.program,s.qty,s.decoration,g.favorites)}}).sort(function(a,b){return b.fit.score-a.fit.score}).slice(0,18);return sectionHead('Recommendation studio','Transparent product-fit ranking for a specific company and program','The score uses buying history, category match, product status, decoration compatibility, quantity, program keywords, and favorites. It does not predict purchase intent.')+studioControls(g)+(s.company?'<div class="pc3-card-grid">'+rows.map(function(x){return '<div class="pc3-card"><div class="pc3-card-name">'+esc(x.product.brand+' '+x.product.name)+'</div><div class="pc3-card-meta">'+esc(x.product.category+' · '+x.product.stockStatus+' · '+s.decoration+' min '+x.fit.compatibility.min)+'</div><div class="pc3-card-value">'+x.fit.score+'/100</div><div class="pc3-card-copy">'+esc(x.fit.reasons.join(' · ')||'No positive evidence recorded.')+'<br>'+esc(x.fit.compatibility.copy)+'</div><div class="pc3-bar"><span style="width:'+x.fit.score+'%"></span></div><div class="pc3-mini-actions"><button class="pc3-mini-btn good" onclick="_rp2ProductsRecommend(\''+encodeURIComponent(x.product.key)+'\')">Create recommendation</button><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpen(\''+encodeURIComponent(x.product.key)+'\')">Product</button></div></div>'}).join('')+'</div>':empty('Choose a company to score products','Select a company, program, quantity, and decoration method.'))+sectionHead('Saved customer recommendations','Good, Better, and Best options with verification status','Saved options preserve the product snapshot and planning assumptions.')+(g.recommendations.length?'<div class="pc3-list">'+g.recommendations.map(recCard).join('')+'</div>':empty('No recommendations are saved','Create a recommendation from the scored studio or catalog.'))}
 function assortmentsView(g){return sectionHead('Customer catalogs and assortments','Company-specific collections of saved recommendations','Assortments organize options for presentation. They are not quotes and do not reserve inventory.')+'<div class="pc3-actions" style="margin-top:0"><button class="pc3-btn primary" onclick="_rp2ProductsNewAssortment()">＋ Build assortment</button></div>'+(g.assortments.length?'<div class="pc3-card-grid">'+g.assortments.map(function(a){var total=a.recommendations.reduce(function(s,r){return s+(r.planningTotal||r.planningUnitPrice*r.quantity)},0);return '<div class="pc3-card"><div class="pc3-card-name">'+esc(a.company+' · '+a.name)+'</div><div class="pc3-card-meta">'+esc((a.program||'No program')+' · '+a.status+' · '+a.recommendations.length+' options')+'</div><div class="pc3-card-value">'+(total?money(total):'Price TBD')+'</div><div class="pc3-card-copy">'+esc(a.notes||'Customer assortment notes not recorded.')+'</div><div class="pc3-tags">'+TIERS.map(function(t){return'<span class="pc3-tag">'+t+' '+a.recommendations.filter(function(r){return r.tier===t}).length+'</span>'}).join('')+(a.quoteNumber?'<span class="pc3-tag info">'+esc(a.quoteNumber)+'</span>':'')+'</div><div class="pc3-mini-actions"><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpenAssortment(\''+encodeURIComponent(a.id)+'\')">Open</button><button class="pc3-mini-btn warn" onclick="_rp2ProductsQuoteAssortment(\''+encodeURIComponent(a.id)+'\')">Quote handoff</button></div></div>'}).join('')+'</div>':empty('No customer assortment is saved','Build an assortment from recommendations for the same company.'))+sectionHead('Good / Better / Best coverage','Recommendation tiers by customer and program','Tiers are presentation labels—not automatic quality or price guarantees.')+'<div class="pc3-option-grid">'+TIERS.map(function(t){var rows=g.recommendations.filter(function(r){return r.tier===t});return '<div class="pc3-option '+t.toLowerCase()+'"><div class="pc3-option-label">'+t+' options</div><div class="pc3-option-name">'+rows.length+' recommendations</div><div class="pc3-option-score">'+(rows.length?Math.round(rows.reduce(function(s,r){return s+r.score.score},0)/rows.length):0)+'/100 avg fit</div><div class="pc3-option-copy">'+esc(rows.slice(0,5).map(function(r){return r.company+' · '+r.product.name}).join(' | ')||'No recommendations in this tier.')+'</div></div>'}).join('')+'</div>'}
 function samplesView(g){var favs=g.products.filter(function(p){return g.favorites[productKey(p)]});return sectionHead('Samples and favorites','Physical sample requests, return commitments, and rep-curated product shortcuts','A requested sample is not proof that the vendor accepted, shipped, or delivered it.')+sectionHead('Open sample workflow','Requested, ordered, shipped, delivered, and return-due samples','Update the status only when the real event occurs.')+(g.samples.length?'<div class="pc3-list">'+g.samples.map(function(s){var w=sampleWarnings(s);return '<div class="pc3-rec"><div class="pc3-rec-icon">📦</div><div><div class="pc3-rec-title">'+esc(s.company+' · '+s.productName)+'</div><div class="pc3-rec-meta">'+esc(s.status+' · '+(s.color||'Color TBD')+' · '+(s.size||'Size TBD')+' · Qty '+s.qty)+'</div><div class="pc3-rec-copy">'+esc(s.notes||'No sample notes recorded.')+'</div><div class="pc3-tags">'+(w.length?'<span class="pc3-tag risk">'+w.length+' warnings</span>':'<span class="pc3-tag good">On track</span>')+'</div></div><div class="pc3-rec-side">Expected '+fmt(s.expectedDate)+'<div class="pc3-mini-actions"><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpenSample(\''+encodeURIComponent(s.id)+'\')">Open</button><button class="pc3-mini-btn good" onclick="_rp2ProductsSampleTask(\''+encodeURIComponent(s.id)+'\')">Action Center</button></div></div></div>'}).join('')+'</div>':empty('No samples are tracked','Request a sample from a customer recommendation.'))+sectionHead('Favorite products','Rep-curated shortcuts from the visible catalog','Favorites influence recommendation scoring slightly but do not override customer evidence.')+(favs.length?'<div class="pc3-product-grid">'+favs.map(function(p){return productCard(p,g)}).join('')+'</div>':empty('No products are favorited','Favorite frequently used products from the catalog.'))}
 function decorationView(g){var short=g.recommendations.filter(function(r){return !compatibility(r.product,r.decoration,r.quantity).ok});return sectionHead('Decoration and pricing control','Compatibility, modeled minimums, planning prices, and verification checkpoints','Screen print uses a 24-piece modeled floor and embroidery uses 12 pieces unless the product minimum is higher.')+'<div class="pc3-insight-grid"><div class="pc3-insight"><div class="pc3-insight-icon">🎨</div><div class="pc3-insight-label">Screen-print floor</div><div class="pc3-insight-value">24</div><div class="pc3-insight-copy">Product-specific minimum may be higher.</div></div><div class="pc3-insight"><div class="pc3-insight-icon">🧵</div><div class="pc3-insight-label">Embroidery floor</div><div class="pc3-insight-value">12</div><div class="pc3-insight-copy">Product-specific minimum may be higher.</div></div><div class="pc3-insight"><div class="pc3-insight-icon">💲</div><div class="pc3-insight-label">Planning prices</div><div class="pc3-insight-value">'+g.recommendations.filter(function(r){return r.planningUnitPrice>0}).length+'</div><div class="pc3-insight-copy">Preliminary prices are not confirmed quote pricing.</div></div><div class="pc3-insight"><div class="pc3-insight-icon">✓</div><div class="pc3-insight-label">Fully verified</div><div class="pc3-insight-value">'+g.recommendations.filter(function(r){return r.availabilityVerified&&r.leadTimeVerified&&!r.warnings.length}).length+'</div><div class="pc3-insight-copy">Availability and timing explicitly verified.</div></div></div>'+sectionHead('Compatibility exceptions','Saved recommendations with method or quantity conflicts','Resolve the product, decoration method, or quantity before customer commitment.')+(short.length?'<div class="pc3-list">'+short.map(recCard).join('')+'</div>':empty('No saved compatibility conflicts','Every saved recommendation meets the modeled method and quantity checks.'))+sectionHead('Recommendation verification matrix','Price, availability, lead time, decoration, and minimum quantity','The chart shows completed verification checkpoints across saved recommendations.')+'<div class="pc3-panel"><div class="pc3-chart"><canvas id="pc3-chart"></canvas></div></div>'}
 function reorderForecastRows(g){
  var map={};
  g.history.forEach(function(l){
   if(!l||!l.company||(!l.sku&&!l.name))return;
   var pk=norm(l.sku||l.name),key=norm(l.company)+'|'+pk,r=map[key]||(map[key]={key:key,company:l.company,sku:l.sku,name:l.name||l.sku,category:l.category||'Other',units:0,revenue:0,orders:{},dates:{}});
   r.units+=Math.max(0,n(l.qty));r.revenue+=n(l.amount);
   var ok=l.orderNumber||iso(l.date);if(ok){var o=r.orders[ok]||(r.orders[ok]={orderNumber:ok,date:l.date,qty:0,revenue:0});o.qty+=Math.max(0,n(l.qty));o.revenue+=n(l.amount)}
   var d=iso(l.date);if(d)r.dates[d]=1
  });
  return Object.keys(map).map(function(k){
   var r=map[k],dates=Object.keys(r.dates).sort(),gaps=[],orders=Object.keys(r.orders).map(function(x){return r.orders[x]}).sort(function(a,b){return(b.date?b.date.getTime():0)-(a.date?a.date.getTime():0)});
   for(var i=1;i<dates.length;i++){var gap=days(dates[i-1],dates[i]);if(gap!=null&&gap>0)gaps.push(gap)}
   r.orderCount=orders.length;r.lastDate=dates.length?stamp(dates[dates.length-1]):null;r.avgGap=gaps.length?Math.round(gaps.reduce(function(s,x){return s+x},0)/gaps.length):null;
   r.lastQty=orders[0]?Math.round(orders[0].qty):0;r.avgQty=orders.length?Math.round(orders.reduce(function(s,o){return s+o.qty},0)/orders.length):0;
   var mean=r.avgGap||0,variance=gaps.length?gaps.reduce(function(s,x){return s+Math.pow(x-mean,2)},0)/gaps.length:0,cv=mean?Math.sqrt(variance)/mean:1;
   r.confidence=gaps.length?Math.max(10,Math.min(95,30+gaps.length*16-Math.round(cv*35))):0;
   r.confidenceLabel=r.confidence>=75?'High':r.confidence>=55?'Moderate':r.confidence>=35?'Directional':r.confidence?'Low':'Insufficient';
   r.nextDate=r.avgGap&&r.lastDate?new Date(r.lastDate.getTime()+r.avgGap*86400000):null;
   r.gap=r.nextDate?days(now(),r.nextDate):null;
   r.status=!r.nextDate?'insufficient':r.gap<-14?'overdue':r.gap<=30?'due':r.gap<=60?'upcoming':'later';
   var match=g.products.filter(function(p){return norm(p.sku||p.name)===norm(r.sku||r.name)})[0];r.product=match||null;
   return r
  }).sort(function(a,b){var rank={overdue:0,due:1,upcoming:2,later:3,insufficient:4};return(rank[a.status]-rank[b.status])||(b.confidence-a.confidence)||(b.revenue-a.revenue)})
 }
 function reorderLabel(r){if(r.status==='overdue')return{tone:'risk',title:'Past forecast',copy:Math.abs(r.gap)+' days past directional date'};if(r.status==='due')return{tone:'warn',title:'Review now',copy:r.gap<0?Math.abs(r.gap)+' days past forecast':'Forecast in '+r.gap+' days'};if(r.status==='upcoming')return{tone:'info',title:'Upcoming',copy:'Forecast in '+r.gap+' days'};if(r.status==='later')return{tone:'good',title:'Later',copy:'Forecast in '+r.gap+' days'};return{tone:'info',title:'Not enough history',copy:'Repeat dated purchases required'}}
 function reorderCenter(g){
  var rows=reorderForecastRows(g),due=rows.filter(function(r){return r.status==='overdue'||r.status==='due'}),upcoming=rows.filter(function(r){return r.status==='upcoming'}),companies={};rows.forEach(function(r){companies[norm(r.company)]=1});
  var dueRevenue=due.reduce(function(s,r){return s+r.revenue},0);
  return sectionHead('Reorder Center 4.0','Portfolio-wide customer-product timing signals','Forecasts use loaded dated purchases. They prioritize conversations and never guarantee demand, availability, or an order.')
   +'<div class="pc3-kpis" style="margin-bottom:16px">'+kpi('Review now',due.length,due.filter(function(r){return r.status==='overdue'}).length+' past forecast')+kpi('Upcoming 60 days',upcoming.length,'Prepare conversations early')+kpi('Customers represented',Object.keys(companies).length,'Rep-owned purchase history')+kpi('Historical revenue',money(rows.reduce(function(s,r){return s+r.revenue},0)),'Loaded product-line evidence')+kpi('Due-product revenue',money(dueRevenue),'Historical value, not projected revenue')+kpi('High confidence',rows.filter(function(r){return r.confidence>=75}).length,'Stable repeat intervals')+kpi('Insufficient cadence',rows.filter(function(r){return r.status==='insufficient'}).length,'Only one or no dated purchase')+kpi('Loaded products',rows.length,'Customer-product combinations')+'</div>'
   +'<div class="pc4-reorder-disclosure"><strong>How to use this:</strong> start with past-forecast and review-now records, validate whether the program still exists, verify the decision maker and timing, then create a dated follow-up or quote. Do not tell the customer the system predicts they will order.</div>'
   +(rows.length?'<div class="pc4-reorder-grid">'+rows.slice(0,60).map(function(r){var s=reorderLabel(r),image=r.product&&r.product.imageUrl?'<img src="'+esc(r.product.imageUrl)+'" alt="">':icon(r.product||r);return '<article class="pc4-reorder-card '+r.status+'"><div class="pc4-reorder-top"><div class="pc4-reorder-icon">'+image+'</div><div><button class="pc4-reorder-company" onclick="_rp2ProductsOpenReorderCompany(\''+encodeURIComponent(r.company)+'\')">'+esc(r.company)+'</button><div class="pc4-reorder-name">'+esc(r.name)+(r.sku?' · '+esc(r.sku):'')+'</div><div class="pc4-reorder-meta">'+esc(r.category)+' · '+r.orderCount+' orders · '+Math.round(r.units).toLocaleString()+' units</div></div><span class="pc3-tag '+s.tone+'">'+s.title+'</span></div><div class="pc4-reorder-kpis"><div><span>Last purchase</span><strong>'+fmt(r.lastDate)+'</strong></div><div><span>Last qty</span><strong>'+r.lastQty+'</strong></div><div><span>Avg cadence</span><strong>'+(r.avgGap?r.avgGap+'d':'—')+'</strong></div><div><span>Next signal</span><strong>'+fmt(r.nextDate)+'</strong></div></div><div class="pc4-reorder-confidence"><div><span style="width:'+r.confidence+'%"></span></div><b>'+r.confidence+'% '+r.confidenceLabel+'</b><small>'+esc(s.copy)+'</small></div><div class="pc3-mini-actions"><button class="pc3-mini-btn good" onclick="_rp2ProductsCreateReorder(\''+encodeURIComponent(r.company)+'\',\''+encodeURIComponent(r.name)+'\')">Create reminder</button><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpenReorderCompany(\''+encodeURIComponent(r.company)+'\')">Customer products</button><button class="pc3-mini-btn" onclick="_rp2ProductsStudioCompany(\''+encodeURIComponent(r.company)+'\')">Recommend options</button></div></article>'}).join('')+'</div>':empty('No line-item purchase history is available','Upload detailed line-item reports and refresh the rep portal.'))
 }
 function intelligence(g){var companyRows=g.companies.map(function(c){var h=historyFor(c),cats=Object.keys(h.categories).sort(function(a,b){return h.categories[b]-h.categories[a]});return{company:c,history:h,top:cats.slice(0,3),recs:g.recommendations.filter(function(r){return norm(r.company)===norm(c)}).length}}).sort(function(a,b){return b.history.totalQty-a.history.totalQty});return sectionHead('Buying intelligence','Completed-order product history and recommendation coverage by company','Only connected completed-order line history counts as buying evidence. Recommendations and planning prices remain separate.')+'<div class="pc3-card-grid">'+companyRows.slice(0,30).map(function(x){return '<div class="pc3-card"><div class="pc3-card-name">'+esc(x.company)+'</div><div class="pc3-card-meta">'+x.history.orders+' orders · '+x.history.totalQty+' visible units · '+x.recs+' recommendations</div><div class="pc3-card-value">'+esc(x.top[0]||'No category')+'</div><div class="pc3-card-copy">'+esc(x.top.map(function(c){return c+' '+x.history.categories[c]}).join(' · ')||'No product-line detail is available in connected orders.')+'</div><div class="pc3-mini-actions"><button class="pc3-mini-btn good" onclick="_rp2ProductsStudioCompany(\''+encodeURIComponent(x.company)+'\')">Recommend products</button><button class="pc3-mini-btn blue" onclick="_rp2ProductsOpenCompany(\''+encodeURIComponent(x.company)+'\')">Company</button></div></div>'}).join('')+'</div>'+sectionHead('Category buying chart','Visible completed-order units by category','Orders without line-level product detail may appear only as general or imported categories.')+'<div class="pc3-panel"><div class="pc3-chart"><canvas id="pc3-chart"></canvas></div></div>'}
 function historyView(g){var rows=[];arr(g.store.data.events).forEach(function(e){rows.push({date:stamp(e.at),type:e.type,title:e.title,copy:e.copy})});g.recommendations.forEach(function(r){if(r.editable)arr(r.history).forEach(function(h){rows.push({date:stamp(h.at),type:h.type||'Recommendation',title:r.company+' · '+r.product.name,copy:h.copy||''})})});rows=rows.filter(function(r){return r.date}).sort(function(a,b){return b.date-a.date});return sectionHead('Catalog audit and governance','Products, favorites, recommendations, assortments, samples, tasks, and quote handoffs','The audit reflects rep-scoped local workflow changes, not vendor inventory or pricing system events.')+(rows.length?'<div class="pc3-history">'+rows.slice(0,400).map(function(r){return '<div class="pc3-history-row"><div class="pc3-history-date">'+fmt(r.date)+'</div><div class="pc3-history-type">'+esc(r.type)+'</div><div class="pc3-history-title">'+esc(r.title)+'</div><div class="pc3-history-copy">'+esc(r.copy)+'</div></div>'}).join('')+'</div>':empty('No product audit events are recorded','Create, import, favorite, recommend, sample, assort, or quote a product to begin the audit trail.'))+sectionHead('Audit event chart','Cumulative local Product Center events','Connected catalog changes are not represented as local audit events.')+'<div class="pc3-panel"><div class="pc3-chart"><canvas id="pc3-chart"></canvas></div></div>'}

 function formField(label,idv,value,type,options){if(type==='textarea')return'<div class="pc3-field"><label>'+label+'</label><textarea id="'+idv+'">'+esc(value||'')+'</textarea></div>';if(type==='select')return'<div class="pc3-field"><label>'+label+'</label><select id="'+idv+'">'+options.map(function(o){var v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return'<option value="'+esc(v)+'" '+(String(value||'')===String(v)?'selected':'')+'>'+esc(l)+'</option>'}).join('')+'</select></div>';return'<div class="pc3-field"><label>'+label+'</label><input id="'+idv+'" type="'+(type||'text')+'" value="'+esc(value||'')+'"></div>'}
 function productForm(g,p){return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">'+(p?'✎':'＋')+'</div><div class="pc3-modal-kick">'+(p?'Edit local product':'Add product')+'</div><div class="pc3-modal-title">'+(p?esc(p.brand+' '+p.name):'Create a product intelligence record')+'</div><div class="pc3-modal-sub">Record product facts, preliminary pricing, decoration compatibility, and verification notes.</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-form"><div class="pc3-form-grid-3">'+formField('Brand','pc3-f-brand',p&&p.brand||'')+formField('Product name','pc3-f-name',p&&p.name||'')+formField('SKU / style','pc3-f-sku',p&&p.sku||'')+'</div><div class="pc3-form-grid-3">'+formField('Category','pc3-f-category',p&&p.category||'Other','select',TYPES)+formField('Subcategory','pc3-f-subcategory',p&&p.subcategory||'')+formField('Status','pc3-f-status',p&&p.status||'Active','select',['Active','Inactive','Discontinued'])+'</div>'+formField('Description','pc3-f-description',p&&p.description||'','textarea')+'<div class="pc3-form-grid-3">'+formField('Base cost','pc3-f-cost',p&&p.baseCost||0,'number')+formField('Planning sell price','pc3-f-price',p&&p.planningPrice||0,'number')+formField('Minimum quantity','pc3-f-min',p&&p.minQty||1,'number')+'</div>'+formField('Pricing note','pc3-f-pricenote',p&&p.priceNote||'','textarea')+'<div class="pc3-form-grid-3">'+formField('Availability','pc3-f-stock',p&&p.stockStatus||'Needs Verification','select',['In Stock','Limited','Needs Verification','Unavailable'])+formField('Lead time','pc3-f-lead',p&&p.leadTime||'')+formField('Season','pc3-f-season',p&&p.season||'Year-Round')+'</div><div class="pc3-form-grid">'+formField('Colors','pc3-f-colors',p&&p.colors.join(', ')||'')+formField('Sizes','pc3-f-sizes',p&&p.sizes.join(', ')||'')+'</div><div class="pc3-form-grid">'+formField('Decoration methods','pc3-f-methods',p&&p.decorationMethods.join(', ')||'Screen Print, Embroidery')+formField('Tags','pc3-f-tags',p&&p.tags.join(', ')||'')+'</div><div class="pc3-form-grid">'+formField('Product URL','pc3-f-url',p&&p.url||'')+formField('Image URL','pc3-f-image',p&&p.imageUrl||'')+'</div></div><div class="pc3-disclosure"><strong>Product boundary:</strong> planning price, stock status, and lead time are advisory fields. Verify current supplier data before presenting a firm quote or delivery commitment.</div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Cancel</button>'+(p?'<button class="pc3-btn" onclick="_rp2ProductsDelete(\''+encodeURIComponent(p.key)+'\')">Delete</button>':'')+'<button class="pc3-btn primary" onclick="_rp2ProductsSave(\''+(p?encodeURIComponent(p.key):'')+'\')">'+(p?'Save changes':'Add product')+'</button></div></aside></div>'}
 function recommendationForm(g,p,r){var company=r&&r.company||window._rp2ProductsStudio.company||'',contacts=company?contactsFor(company):[];return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">✦</div><div class="pc3-modal-kick">Customer recommendation</div><div class="pc3-modal-title">'+esc(p.brand+' '+p.name)+'</div><div class="pc3-modal-sub">Create a Good, Better, or Best option with explicit pricing and verification assumptions.</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-form"><div class="pc3-form-grid">'+formField('Company','pc3-r-company',company,'select',[{value:'',label:'Choose company'}].concat(g.companies.map(function(c){return{value:c,label:c}})))+formField('Contact','pc3-r-contact',r&&r.contactId||'','select',[{value:'',label:'No contact linked'}].concat(contacts.map(function(c){return{value:c.id,label:c.name}})))+'</div><div class="pc3-form-grid-3">'+formField('Tier','pc3-r-tier',r&&r.tier||'Good','select',TIERS)+formField('Status','pc3-r-status',r&&r.status||'Draft','select',REC_STATUS)+formField('Program / use case','pc3-r-program',r&&r.program||window._rp2ProductsStudio.program||'')+'</div>'+formField('Customer need','pc3-r-need',r&&r.need||'','textarea')+'<div class="pc3-form-grid-3">'+formField('Quantity','pc3-r-qty',r&&r.quantity||window._rp2ProductsStudio.qty||24,'number')+formField('Decoration','pc3-r-decoration',r&&r.decoration||window._rp2ProductsStudio.decoration||'Screen Print','select',METHODS)+formField('Decoration locations','pc3-r-locations',r&&r.locations||'')+'</div><div class="pc3-form-grid-3">'+formField('Planning unit price','pc3-r-price',r&&r.planningUnitPrice||p.planningPrice||0,'number')+formField('Valid until','pc3-r-valid',iso(r&&r.validUntil),'date')+formField('Price note','pc3-r-pricenote',r&&r.priceNote||p.priceNote||'Preliminary planning price; verify before quoting.')+'</div><div class="pc3-form-grid">'+formField('Availability verified','pc3-r-availability',r&&r.availabilityVerified?'Yes':'No','select',['No','Yes'])+formField('Lead time verified','pc3-r-leadtime',r&&r.leadTimeVerified?'Yes':'No','select',['No','Yes'])+'</div>'+formField('Customer-fit rationale','pc3-r-fitnotes',r&&r.fitNotes||'','textarea')+'</div><div class="pc3-disclosure"><strong>Recommendation boundary:</strong> this is not a quote, order, inventory reservation, or delivery promise. Quote handoff should occur only after current pricing, stock, decoration, and production timing are checked.</div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Cancel</button><button class="pc3-btn primary" onclick="_rp2ProductsSaveRec(\''+(r?encodeURIComponent(r.key):'')+'\',\''+encodeURIComponent(p.key)+'\')">'+(r?'Save recommendation':'Create recommendation')+'</button></div></aside></div>'}
 function detail(g,p){var h=g.history.filter(function(l){return norm(l.sku||l.name)===norm(p.sku||p.name)}),recs=g.recommendations.filter(function(r){return r.productKey===p.key});return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">'+icon(p)+'</div><div class="pc3-modal-kick">'+esc(p.brand+' · '+p.category+' · '+(p.source==='local'?'Local':'Connected'))+'</div><div class="pc3-modal-title">'+esc(p.name)+'</div><div class="pc3-modal-sub">'+esc((p.sku||'No SKU')+' · '+p.stockStatus+' · Min '+p.minQty)+'</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-detail-grid" style="margin-top:17px"><div class="pc3-detail"><div class="pc3-detail-label">Planning pricing</div><div class="pc3-detail-value">Cost '+(p.baseCost?money(p.baseCost):'TBD')+'\nSell '+(p.planningPrice?money(p.planningPrice):'TBD')+'\n'+esc(p.priceNote||'No pricing note')+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Decoration</div><div class="pc3-detail-value">'+esc(p.decorationMethods.join(', ')||'No methods listed')+'\nScreen print floor '+methodMin('Screen Print',p)+'\nEmbroidery floor '+methodMin('Embroidery',p)+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Options</div><div class="pc3-detail-value">Colors: '+esc(p.colors.join(', ')||'Not recorded')+'\nSizes: '+esc(p.sizes.join(', ')||'Not recorded')+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Availability and timing</div><div class="pc3-detail-value">'+esc(p.stockStatus)+'\n'+esc(p.leadTime||'Lead time not recorded')+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Completed-order evidence</div><div class="pc3-detail-value">'+h.length+' visible line records\n'+h.reduce(function(s,l){return s+l.qty},0)+' visible units</div></div><div class="pc3-detail"><div class="pc3-detail-label">Recommendation use</div><div class="pc3-detail-value">'+recs.length+' saved recommendations\n'+recs.filter(function(r){return r.status==='Selected'}).length+' selected</div></div></div><div class="pc3-disclosure"><strong>Verification:</strong> URLs, planning prices, stock labels, and lead times may become stale. Confirm supplier data before a quote or customer commitment.</div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Close</button>'+(p.url?'<button class="pc3-btn blue" onclick="window.open(\''+esc(p.url).replace(/'/g,"\\'")+'\',\'_blank\',\'noopener\')">Product link</button>':'')+'<button class="pc3-btn good" onclick="_rp2ProductsRecommend(\''+encodeURIComponent(p.key)+'\')">Recommend</button><button class="pc3-btn warn" onclick="_rp2ProductsFavorite(\''+encodeURIComponent(p.key)+'\')">Favorite</button>'+(p.editable?'<button class="pc3-btn primary" onclick="_rp2ProductsEdit(\''+encodeURIComponent(p.key)+'\')">Edit</button>':'<button class="pc3-btn primary" onclick="_rp2ProductsImport(\''+encodeURIComponent(p.key)+'\')">Import locally</button>')+'</div></aside></div>'}
 function recDetail(r){return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">✦</div><div class="pc3-modal-kick">'+esc(r.tier+' · '+r.status+' · '+r.company)+'</div><div class="pc3-modal-title">'+esc(r.product.brand+' '+r.product.name)+'</div><div class="pc3-modal-sub">'+esc(r.quantity+' units · '+r.decoration+' · '+(r.program||'No program'))+'</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-detail-grid" style="margin-top:17px"><div class="pc3-detail"><div class="pc3-detail-label">Planning price</div><div class="pc3-detail-value">'+(r.planningUnitPrice?money(r.planningUnitPrice)+'/ea\n'+money(r.planningTotal||r.planningUnitPrice*r.quantity):'Price TBD')+'\n'+esc(r.priceNote||'No pricing note')+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Verification</div><div class="pc3-detail-value">Availability '+(r.availabilityVerified?'verified':'not verified')+'\nLead time '+(r.leadTimeVerified?'verified':'not verified')+'\nValid until '+fmt(r.validUntil)+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Fit score</div><div class="pc3-detail-value">'+r.score.score+'/100\n'+esc(r.score.reasons.join(' · ')||'No positive evidence')+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Customer fit</div><div class="pc3-detail-value">'+esc(r.fitNotes||r.need||'Not recorded')+'</div></div></div>'+sectionHead('Recommendation warnings','Exact unresolved verification or compatibility issues','Resolve warnings before customer commitment.')+(r.warnings.length?'<div class="pc3-priority-list">'+r.warnings.map(function(w){return'<div class="pc3-priority '+(w.level==='high'?'high':'medium')+'"><div class="pc3-priority-icon">'+w.icon+'</div><div><div class="pc3-priority-title">'+esc(w.title)+'</div><div class="pc3-priority-copy">'+esc(w.copy)+'</div></div><div></div></div>'}).join('')+'</div>':empty('No active recommendation warnings','All modeled checks are satisfied.'))+'<div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Close</button>'+(r.editable?'<button class="pc3-btn" onclick="_rp2ProductsEditRec(\''+encodeURIComponent(r.key)+'\')">Edit</button><button class="pc3-btn good" onclick="_rp2ProductsSample(\''+encodeURIComponent(r.key)+'\')">Request sample</button><button class="pc3-btn primary" onclick="_rp2ProductsQuote(\''+encodeURIComponent(r.key)+'\')">Deal Desk handoff</button>':'')+'</div></aside></div>'}
 function assortmentForm(g){var company=window._rp2ProductsStudio.company||'',rows=g.recommendations.filter(function(r){return r.editable&&(!company||norm(r.company)===norm(company))});return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">▦</div><div class="pc3-modal-kick">Customer assortment</div><div class="pc3-modal-title">Build a customer-specific catalog</div><div class="pc3-modal-sub">Select saved recommendations for one company and program.</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-form"><div class="pc3-form-grid">'+formField('Company','pc3-a-company',company,'select',[{value:'',label:'Choose company'}].concat(g.companies.map(function(c){return{value:c,label:c}})))+formField('Assortment name','pc3-a-name','')+'</div><div class="pc3-form-grid">'+formField('Program','pc3-a-program',window._rp2ProductsStudio.program||'')+formField('Status','pc3-a-status','Draft','select',['Draft','Ready to Share','Customer Reviewing','Selected','Archived'])+'</div>'+formField('Notes','pc3-a-notes','','textarea')+'<div class="pc3-panel"><div class="pc3-section-kick">Select recommendations</div><div class="pc3-list" style="margin-top:10px">'+rows.map(function(r){return'<label class="pc3-rec"><input type="checkbox" data-pc3-assort="'+esc(r.id)+'" style="margin-top:12px"><div><div class="pc3-rec-title">'+esc(r.company+' · '+r.tier+' · '+r.product.name)+'</div><div class="pc3-rec-meta">'+r.quantity+' · '+esc(r.decoration)+' · '+(r.planningUnitPrice?money(r.planningUnitPrice)+'/ea':'Price TBD')+'</div></div><div></div></label>'}).join('')+'</div></div></div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Cancel</button><button class="pc3-btn primary" onclick="_rp2ProductsSaveAssortment()">Save assortment</button></div></aside></div>'}
 function sampleForm(r){return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">📦</div><div class="pc3-modal-kick">Sample workflow</div><div class="pc3-modal-title">'+esc(r.product.brand+' '+r.product.name)+'</div><div class="pc3-modal-sub">'+esc(r.company+' · '+r.tier+' recommendation')+'</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-form"><div class="pc3-form-grid-3">'+formField('Status','pc3-s-status','Requested','select',SAMPLE_STATUS)+formField('Quantity','pc3-s-qty',1,'number')+formField('Requested date','pc3-s-requested',iso(now()),'date')+'</div><div class="pc3-form-grid">'+formField('Color','pc3-s-color','')+formField('Size','pc3-s-size','')+'</div><div class="pc3-form-grid">'+formField('Expected date','pc3-s-expected','','date')+formField('Return due','pc3-s-return','','date')+'</div>'+formField('Sample notes','pc3-s-notes','','textarea')+'</div><div class="pc3-disclosure"><strong>Sample boundary:</strong> Requested means the rep recorded the request. It does not mean the vendor accepted, shipped, or delivered the sample.</div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Cancel</button><button class="pc3-btn primary" onclick="_rp2ProductsSaveSample(\''+encodeURIComponent(r.key)+'\')">Create sample request</button></div></aside></div>'}
 function sampleDetail(s){return'<div class="pc3-modal-wrap" onclick="if(event.target===this)_rp2ProductsCloseModal()"><aside class="pc3-modal"><div class="pc3-modal-head"><div><div class="pc3-modal-icon">📦</div><div class="pc3-modal-kick">'+esc(s.status+' · '+s.company)+'</div><div class="pc3-modal-title">'+esc(s.productName)+'</div><div class="pc3-modal-sub">'+esc((s.color||'Color TBD')+' · '+(s.size||'Size TBD')+' · Qty '+s.qty)+'</div></div><button class="pc3-close" onclick="_rp2ProductsCloseModal()">×</button></div><div class="pc3-detail-grid" style="margin-top:17px"><div class="pc3-detail"><div class="pc3-detail-label">Dates</div><div class="pc3-detail-value">Requested '+fmt(s.requestedAt)+'\nExpected '+fmt(s.expectedDate)+'\nDelivered '+fmt(s.deliveredAt)+'\nReturn due '+fmt(s.returnDue)+'</div></div><div class="pc3-detail"><div class="pc3-detail-label">Notes</div><div class="pc3-detail-value">'+esc(s.notes||'No notes')+'</div></div></div><div class="pc3-modal-actions"><button class="pc3-btn" onclick="_rp2ProductsCloseModal()">Close</button><button class="pc3-btn good" onclick="_rp2ProductsSampleTask(\''+encodeURIComponent(s.id)+'\')">Action Center</button></div></aside></div>'}
 function modal(g){var m=window._rp2ProductsModal;if(!m)return'';if(m.mode==='newProduct')return productForm(g,null);if(m.mode==='newAssortment')return assortmentForm(g);var p=m.key?productByKey(decodeURIComponent(m.key),g.products):null;if(m.mode==='product'&&p)return detail(g,p);if(m.mode==='editProduct'&&p&&p.editable)return productForm(g,p);var r=m.key?g.recommendations.filter(function(x){return x.key===decodeURIComponent(m.key)})[0]:null;if(m.mode==='recommend'&&p)return recommendationForm(g,p,null);if(m.mode==='rec'&&r)return recDetail(r);if(m.mode==='editRec'&&r&&r.editable)return recommendationForm(g,r.product,r);if(m.mode==='sample'&&r&&r.editable)return sampleForm(r);var s=m.id?g.samples.filter(function(x){return x.id===decodeURIComponent(m.id)})[0]:null;if(m.mode==='sampleDetail'&&s)return sampleDetail(s);return''}

 function render(){var e=document.getElementById('rp2-page');if(e)e.innerHTML=window._rp2ProductsV3();setTimeout(function(){try{window._rp2ProductsDraw();window._rp2ProductsFilter()}catch(x){}},0)}
 function val(idv){var e=document.getElementById(idv);return e?clean(e.value):''}
